import React, { useState, useEffect } from 'react';
import {
  Dialog, DialogTitle, DialogContent, DialogActions, Button, Typography,
  Box, Divider, Chip, Accordion, AccordionSummary, AccordionDetails,
  TextField, InputAdornment, Stack, IconButton,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import SearchIcon from '@mui/icons-material/Search';
import CloseIcon from '@mui/icons-material/Close';

/**
 * صفحه راهنمای سراسری — با F1 باز می‌شود.
 * شامل راهنمای کامل همهٔ بخش‌های برنامه + راهنمای دستیار منابع انسانی.
 */
const HELP_SECTIONS = [
  {
    title: '🏠 داشبورد',
    content: [
      'نمای کلی سازمان: تعداد پرسنل، نرخ خروج، تولدهای آینده، قراردادهای در شرف انقضا و هشدارها.',
      'کارت‌های KPI در بالای صفحه، آمار لحظه‌ای را نشان می‌دهند.',
    ],
  },
  {
    title: '👥 پرسنل',
    content: [
      'لیست، جستجو و فیلتر پرسنل.',
      'افزودن پرسنل: فرم کامل ۴ بخشی (اطلاعات فردی، تماس، شغلی، مدارک، سوابق کاری و ارزیابی).',
      'پرونده پرسنلی: ۶ تب (فردی، شغلی، دریافتی‌ها، کارکرد، تغییرات، مدارک).',
      'عکس پرسنلی: در فرم یا تب مدارک آپلود می‌شود و در همه‌جا نمایش داده می‌شود.',
    ],
  },
  {
    title: '📞 دفترچه تلفن',
    content: [
      'کارت‌های تماس شیشه‌ای با عکس، موبایل، تلفن، ایمیل و آدرس.',
      'جستجو و فیلتر بر اساس دپارتمان.',
      'خروجی اکسل برای استفاده آفلاین.',
    ],
  },
  {
    title: '🔍 جستجوی پیشرفته',
    content: [
      'جستجو در پرسنل و مدارک با فیلترهای ترکیبی.',
      'فیلترها: دپارتمان، عنوان شغلی، محل، جنسیت، تأهل، وضعیت و نوع مدرک.',
      'جستجوی فازی (Trigram) روی PostgreSQL — عبارت ناقص هم پیدا می‌شود.',
    ],
  },
  {
    title: '🌳 چارت سازمانی',
    content: [
      'درخت سلسله‌مراتبی با اتصالات خودکار.',
      'تمرکز بر شاخه: انتخاب یک گره برای نمایش زنجیرهٔ بالادستی + زیرمجموعه‌ها.',
      'ویرایش: افزودن/ویرایش/حذف جایگاه + تخصیص نفرات.',
      'چاپ/PDF: کل چارت (یا شاخه انتخابی) با مقیاس خودکار چاپ می‌شود.',
    ],
  },
  {
    title: '📊 گزارشات',
    content: [
      '۱۵+ نمودار: ترکیب جنسیتی، دپارتمان‌ها، عنوان شغلی، محل، بیمه، سن، نرخ خروج و ...',
      'بخش تولدهای ۷ روز آینده (شمسی).',
      'خلاصه مکاتبات + خلاصه حقوق و مزایا.',
      'دستیار منابع انسانی برای پرسش و پاسخ متنی.',
    ],
  },
  {
    title: '⚙️ تعاریف اولیه',
    content: [
      'مشخصات شرکت (لوگو، اطلاعات حقوقی، تماس).',
      'دپارتمان‌ها، عناوین شغلی، محل‌های استقرار، لیست بیمه، انواع مدارک، انواع قرارداد و سازمان‌ها.',
      'این موارد در dropdown های سراسر برنامه استفاده می‌شوند.',
    ],
  },
  {
    title: '📝 ورود اطلاعات',
    content: [
      'ثبت مرخصی، غیبت، حقوق، مزایا و کسورات.',
      '۵ تب: مرخصی، غیبت، حقوق، مزایا، کسورات.',
      'تراکنش‌های اخیر در پایین صفحه نمایش داده می‌شود.',
    ],
  },
  {
    title: '✉️ مکاتبات',
    content: [
      'نامه‌های وارده، صادره، ابلاغ‌ها و فرم‌ها.',
      'هر مورد: شماره، تاریخ، موضوع، اولویت و پیوست.',
      'تب سازمانی: مکاتبات با اداره مالیات، تأمین اجتماعی و سایر سازمان‌ها.',
    ],
  },
  {
    title: '🏆 ارزیابی',
    content: [
      'امتیازدهی وزنی کارکنان بر اساس ۱۲ معیار:',
      'عملکرد، رضایت شغلی، تحصیلات، حضور و کارکرد، انضباط (جرائم)، مسافت، سابقه، افزایش حقوق، مزایا، مأموریت، قرارداد، نوبت کاری.',
      'رتبه‌بندی با نوار پیشرفت رنگی + تفکیک جزئیات هر کارمند.',
    ],
  },
  {
    title: '👤 تنظیمات',
    content: [
      'تنظیمات عمومی (ذخیره‌سازی، هشدار، مرخصی، نمایش).',
      'کاربران و نقش‌ها.',
      'درون‌ریزی اکسل (بارگذاری گروهی).',
      'ظاهر: ۵ مد نمایش — روشن، تاریک، F مود، F مود روشن، کوراساوا مود (سیاه‌وسفید).',
    ],
  },
  {
    title: '🤖 دستیار منابع انسانی',
    content: [
      'دستیار هوشمند و کاملاً آفلاین که از داده‌های واقعی سازمان پاسخ می‌دهد.',
      '📌 نمونه سؤالات:',
      '• «تاریخ استخدام [نام] کی بوده؟»',
      '• «آدرس [نام] رو بگو»',
      '• «کارکرد [نام] در سال ۱۴۰۴ چقدر بوده؟»',
      '• «آخرین کارکرد [نام] چقدر بود؟»',
      '• «حقوق و مزایای [نام] چقدر بود؟»',
      '• «مزایای رفاهی [نام] چیست؟»',
      '• «مرخصی [نام] چقدر مانده؟»',
      '• «جرائم [نام] چیست؟»',
      '• «مدارک [نام] چیست؟»',
      '• «سوابق کاری [نام] چیست؟» (۱۰ نوع سؤال)',
      '• «چه کسانی احتمال استعفا دارند؟»',
      '• «بهترین کارمند کیه؟» (رتبه‌بندی)',
      '• «نمودار دپارتمان‌ها رو نشون بده»',
      '• سؤالات مرکب: «کارکرد و حقوق و مزایای [نام] در ۱۴۰۴»',
    ],
  },
  {
    title: '⌨️ میانبرهای صفحه‌کلید',
    content: [
      'F1: باز کردن این راهنما.',
      'Enter: ارسال پیام در دستیار.',
    ],
  },
];

const HelpDialog = () => {
  const [open, setOpen] = useState(false);
  const [search, setSearch] = useState('');

  useEffect(() => {
    const handler = (e) => {
      if (e.key === 'F1') {
        e.preventDefault();
        setOpen(prev => !prev);
      }
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);

  const normalized = search.trim().toLowerCase();
  const filtered = normalized
    ? HELP_SECTIONS.filter(s =>
        s.title.toLowerCase().includes(normalized) ||
        s.content.some(c => c.toLowerCase().includes(normalized))
      )
    : HELP_SECTIONS;

  return (
    <Dialog open={open} onClose={() => setOpen(false)} maxWidth="md" fullWidth>
      <DialogTitle sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <Typography variant="h6" fontWeight={800}>راهنمای کامل برنامه — HRMS</Typography>
        <IconButton onClick={() => setOpen(false)} size="small"><CloseIcon /></IconButton>
      </DialogTitle>

      <DialogContent dividers>
        {/* Search */}
        <TextField
          fullWidth
          size="small"
          placeholder="جستجو در راهنما..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          InputProps={{
            startAdornment: <InputAdornment position="start"><SearchIcon /></InputAdornment>,
          }}
          sx={{ mb: 2 }}
        />

        <Stack spacing={1}>
          {filtered.length === 0 ? (
            <Typography color="textSecondary" textAlign="center" sx={{ py: 4 }}>
              نتیجه‌ای یافت نشد
            </Typography>
          ) : (
            filtered.map(section => (
              <Accordion key={section.title} defaultExpanded={!normalized}>
                <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                  <Typography fontWeight={700}>{section.title}</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
                    {section.content.map((c, i) => (
                      <Typography key={i} variant="body2" sx={{ color: 'text.secondary' }}>
                        {c}
                      </Typography>
                    ))}
                  </Box>
                </AccordionDetails>
              </Accordion>
            ))
          )}
        </Stack>
      </DialogContent>

      <DialogActions sx={{ px: 3, py: 2 }}>
        <Chip size="small" label="F1 برای باز/بسته کردن" variant="outlined" sx={{ mr: 'auto' }} />
        <Button variant="contained" onClick={() => setOpen(false)}>بستن</Button>
      </DialogActions>
    </Dialog>
  );
};

export default HelpDialog;
